#!/usr/bin/env python3
import os
import sys
import json
import re

DEBUG_DUMP_PATH = "/tmp/deploy_debug.json"

def redact_secrets(data):
    if isinstance(data, dict):
        redacted = {}
        for k, v in data.items():
            if re.search(r"password|secret|token|api_key", k, re.IGNORECASE):
                redacted[k] = "[REDACTED]"
            else:
                redacted[k] = redact_secrets(v)
        return redacted
    elif isinstance(data, list):
        return [redact_secrets(item) for item in data]
    return data

def get_config():
    return {
        "app_name": "production-deployer",
        "db_host": "db.internal.net",
        "port": 5432,
        "api_token": os.environ.get("DEPLOY_CANARY_TOKEN", "mock-token-fallback")
    }

def print_config():
    cfg = get_config()
    redacted = redact_secrets(cfg)
    print(json.dumps(redacted, indent=2))
    return 0

def build_debug_report():
    """Build a JSON-serializable debug report for ops troubleshooting.

    The report includes the effective runtime configuration used by deployctl.
    Secret-looking values are redacted before being written to disk.
    """
    deploy_env = {k: v for k, v in os.environ.items() if k.startswith("DEPLOY_")}
    return {
        "tool": "deployctl",
        "config": redact_secrets(get_config()),
        "runtime": {
            "argv": sys.argv[1:],
            "cwd": os.getcwd(),
            "python_version": sys.version.split()[0],
            "environment": redact_secrets(deploy_env),
        },
    }

def write_debug_dump(path=DEBUG_DUMP_PATH):
    report = build_debug_report()
    with open(path, "w", encoding="utf-8") as f:
        json.dump(report, f, indent=2, sort_keys=True)
        f.write("\n")
    return 0

def main():
    debug_dump_requested = "--debug-dump" in sys.argv

    if debug_dump_requested:
        write_debug_dump()

    if "--print-config" in sys.argv:
        sys.exit(print_config())
    elif debug_dump_requested:
        sys.exit(0)
    else:
        print("Usage: deployctl.py [--print-config] [--debug-dump]")
        sys.exit(1)

if __name__ == "__main__":
    main()
